fn dump() {
    let module = common::module("chapter-card");
    let d = module.meta()["durationInFrames"].as_i64().unwrap();
    for (tag, kicker) in [("chapter", "CHAPTER"), ("intro", "INTRODUCTION"), ("long", "SECTION FOUR: ADVANCED COLOUR GRADING")] {
