            let mut out = vec![0u8; stride * h as usize];
            rasterize(&common::shared(), &svg, w, h, &mut out, stride).unwrap();
            let rgb: Vec<u8> = out.chunks_exact(4).flat_map(|p| [p[2], p[1], p[0]]).collect();
